public static void main(String[] args) {
    FastScanner fs = new FastScanner();
    PrintWriter out = new PrintWriter(System.out);

    int n = fs.nextInt();
    int m = fs.nextInt();
    int k = fs.nextInt();

    int[] result = new int[m];
    int[][] test = new int[m][n];
    for (int i = 0; i < m; i++) {
        int c = fs.nextInt();
        for (int j = 0; j < c; j++) {
            int x = fs.nextInt();
            test[i][x - 1] = 1;
        }
        String res = fs.next();
        if (res.equals("o")) {
            result[i] = 1;
        } else {
            result[i] = 0;
        }
    }
    int ans = 0;
    for (int i = 0; i < (1 << n); i++) {
        int[] currentPerm = new int[n];
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) > 0) {
                currentPerm[j] = 1;
            }
        }
        boolean flag = true;
        for (int j = 0; j < m; j++) {
            int realKeys = 0;
            for (int l = 0; l < n; l++) {
                if (currentPerm[l] == 1 && test[j][l] == 1) {
                    realKeys++;
                }
            }
            if (realKeys >= k && result[j] == 0) {
                flag = false;
                break;
            }
            if (realKeys < k && result[j] == 1) {
                flag = false;
                break;
            }
        }
        if (flag) {
            ans++;
        }
    }
    out.println(ans);

    out.close();
}
